-- Deliveries and their lifecycle state.
-- Migrations are additive only (new tables, new nullable or defaulted columns), so the previous
-- application version keeps working against the new schema and a deployment can be rolled back.
-- Never edit this file once it has been applied: Flyway checksums it. Add V2__..., V3__... instead.

CREATE TABLE delivery (
    -- Generated by the application (UUID.randomUUID()), not by the database.
    id             uuid         NOT NULL,
    -- Lengths match the API validation (@Size max 100 / 255).
    recipient_name varchar(100) NOT NULL,
    address        varchar(255) NOT NULL,
    -- Stored as the enum name (@Enumerated(EnumType.STRING)), readable in SQL and safe to reorder.
    status         varchar(20)  NOT NULL,
    -- Optimistic locking (@Version): every update checks and increments it.
    version        bigint       NOT NULL,
    created_at     timestamptz  NOT NULL,
    updated_at     timestamptz  NOT NULL,

    CONSTRAINT pk_delivery PRIMARY KEY (id),
    CONSTRAINT ck_delivery_status
        CHECK (status IN ('CREATED', 'PICKED_UP', 'IN_TRANSIT', 'DELIVERED', 'CANCELLED'))
);
